import{c as a,Q as o,j as t,m as r}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"help/faq.md","filePath":"help/faq.md","lastUpdated":null}'),s={name:"help/faq.md"};function i(d,e,n,c,h,l){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="do-i-need-a-provider-to-use-finsight" tabindex="-1">Do I need a provider to use FinSight? <a class="header-anchor" href="#do-i-need-a-provider-to-use-finsight" aria-label="Permalink to &quot;Do I need a provider to use FinSight?&quot;">​</a></h2><p>No. Budgets, goals, reports, transactions, and the deterministic parts of insights work without one. The Copilot and auto-categorization are the only features that need a provider — and both are opt-in. See <a href="/FinSight/getting-started/configuring-ai">Configuring AI</a>.</p><h2 id="does-finsight-store-my-bank-password" tabindex="-1">Does FinSight store my bank password? <a class="header-anchor" href="#does-finsight-store-my-bank-password" aria-label="Permalink to &quot;Does FinSight store my bank password?&quot;">​</a></h2><p>No. For SimpleFIN, you exchange a SimpleFIN access URL obtained from your bridge. FinSight stores that URL inside your encrypted <code>data.sqlcipher</code> per user and uses it only when you synchronize. No bank password touches your server.</p><h2 id="can-i-self-host-without-docker" tabindex="-1">Can I self-host without Docker? <a class="header-anchor" href="#can-i-self-host-without-docker" aria-label="Permalink to &quot;Can I self-host without Docker?&quot;">​</a></h2><p>The image is the supported distribution. Native <code>cargo run -p finsight-server</code> works for development (<code>FINSIGHT_DATA_DIR=./data</code>) but Docker + the hardened Compose file is the deployment path.</p><h2 id="what-if-i-lose-my-recovery-key-and-my-password" tabindex="-1">What if I lose my recovery key and my password? <a class="header-anchor" href="#what-if-i-lose-my-recovery-key-and-my-password" aria-label="Permalink to &quot;What if I lose my recovery key and my password?&quot;">​</a></h2><p>There is no way back — by design. Each database key is wrapped by both the password-derived KEK and the recovery key. Without either, the DB key cannot be unwrapped and the database cannot be opened. Back up the recovery key.</p><h2 id="how-do-i-back-up" tabindex="-1">How do I back up? <a class="header-anchor" href="#how-do-i-back-up" aria-label="Permalink to &quot;How do I back up?&quot;">​</a></h2><p>Two layers:</p><ol><li><strong>Per-user snapshot</strong> — Settings → Data &amp; backups creates an encrypted snapshot under <code>users/&lt;uuid&gt;/backups/</code>.</li><li><strong>Disaster recovery</strong> — back up the <strong>whole <code>/data</code> volume</strong> (<code>users.db</code> + <code>session.key</code> + every per-user database). A lone <code>data.sqlcipher</code> without <code>users.db</code> cannot be opened.</li></ol><h2 id="is-my-data-synced-across-devices" tabindex="-1">Is my data synced across devices? <a class="header-anchor" href="#is-my-data-synced-across-devices" aria-label="Permalink to &quot;Is my data synced across devices?&quot;">​</a></h2><p>The server at <code>https://&lt;your-origin&gt;</code> is the source of truth. The browser’s seven-day IndexedDB cache is read-only and for offline viewing; it purges on logout. There is no sync to a vendor cloud.</p><h2 id="which-ai-provider-keeps-data-local" tabindex="-1">Which AI provider keeps data local? <a class="header-anchor" href="#which-ai-provider-keeps-data-local" aria-label="Permalink to &quot;Which AI provider keeps data local?&quot;">​</a></h2><p><a href="/FinSight/configuration/ollama">Ollama</a> — inference stays on your LAN/machine. Cloud providers receive the redacted context for the task (merchant + amount for categorization; question-scoped FinancialContext for Copilot).</p><p>See also: <a href="/FinSight/getting-started/privacy">Privacy &amp; Local Data</a>, <a href="/FinSight/help/security">Security &amp; Privacy</a>.</p>',17)])])}const y=a(s,[["render",i]]);export{u as __pageData,y as default};
